sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // Don't run during form loading or on templates
    if (isLoading || isTemplate) {
        return;
    }

    // Get the field name that triggered the change
    var fieldName = control.getTableName() + '.' + control.getName();

    // Initialize the TradeBookUtils script include
    var tradeUtils = new GlideAjax('TradeBookUtils');

    try {
        // Handle different field changes
        switch (control.getName()) {
            case 'stock_name':
                handleStockNameChange(newValue, tradeUtils);
                break;

            case 'buying_price':
                handleBuyingPriceChange(newValue, tradeUtils);
                break;

            case 'stop_loss':
                handleStopLossChange(newValue, tradeUtils);
                break;
        }

        // If both buying price and stop loss are filled, calculate risk and recommendations
        var buyingPrice = g_form.getValue('buying_price');
        var stopLoss = g_form.getValue('stop_loss');

        if (buyingPrice && stopLoss && buyingPrice !== '' && stopLoss !== '') {
            calculateRiskAndRecommendations(buyingPrice, stopLoss, tradeUtils);
        }

    } catch (error) {
        console.error('Error in Trade Book onChange script: ', error);
        g_form.addErrorMessage('An error occurred while validating the form. Please try again.');
    }
}

/**
 * Handle stock name field changes
 */
function handleStockNameChange(stockName, tradeUtils) {
    if (!stockName || stockName.trim() === '') {
        g_form.clearMessages('stock_name');
        return;
    }

    // Clear previous messages
    g_form.clearMessages('stock_name');

    // Validate stock name format
    tradeUtils.addParam('sysparm_name', 'validateStockName');
    tradeUtils.addParam('sysparm_stock_name', stockName);
    tradeUtils.getXMLAnswer(function(response) {
        var result = JSON.parse(response);

        if (!result.success) {
            g_form.showFieldMsg('stock_name', result.message, 'warning');
            if (result.suggestion) {
                g_form.addInfoMessage('Suggestion: ' + result.suggestion);
            }
        } else {
            g_form.hideFieldMsg('stock_name');
        }
    });
}

/**
 * Handle buying price field changes
 */
function handleBuyingPriceChange(buyingPrice, tradeUtils) {
    if (!buyingPrice || buyingPrice.trim() === '') {
        g_form.clearMessages('buying_price');
        return;
    }

    // Clear previous messages
    g_form.clearMessages('buying_price');

    // Validate buying price format and value
    var price = parseFloat(buyingPrice);

    if (isNaN(price) || price <= 0) {
        g_form.showFieldMsg('buying_price', 'Please enter a valid positive price', 'error');
        return;
    }

    // Format the price display
    tradeUtils.addParam('sysparm_name', 'formatCurrency');
    tradeUtils.addParam('sysparm_value', buyingPrice);
    tradeUtils.getXMLAnswer(function(response) {
        var formattedPrice = response;
        g_form.showFieldMsg('buying_price', 'Formatted: ' + formattedPrice, 'info');
    });

    // Provide price-based recommendations
    if (price > 1000) {
        g_form.addInfoMessage('High-value stock detected. Consider position sizing and portfolio allocation.');
    }
}

/**
 * Handle stop loss field changes
 */
function handleStopLossChange(stopLoss, tradeUtils) {
    if (!stopLoss || stopLoss.trim() === '') {
        g_form.clearMessages('stop_loss');
        return;
    }

    // Clear previous messages
    g_form.clearMessages('stop_loss');

    var buyingPrice = g_form.getValue('buying_price');

    if (buyingPrice && buyingPrice !== '') {
        // Validate stop loss against buying price
        tradeUtils.addParam('sysparm_name', 'validateStopLoss');
        tradeUtils.addParam('sysparm_buying_price', buyingPrice);
        tradeUtils.addParam('sysparm_stop_loss', stopLoss);
        tradeUtils.getXMLAnswer(function(response) {
            var result = JSON.parse(response);

            if (!result.success) {
                g_form.showFieldMsg('stop_loss', result.message, 'error');
            } else {
                g_form.showFieldMsg('stop_loss', 'Risk: ' + result.riskPercentage + '%', 'info');
                g_form.hideFieldMsg('stop_loss', true); // Hide error messages
            }
        });
    } else {
        // Format the stop loss display
        tradeUtils.addParam('sysparm_name', 'formatCurrency');
        tradeUtils.addParam('sysparm_value', stopLoss);
        tradeUtils.getXMLAnswer(function(response) {
            var formattedPrice = response;
            g_form.showFieldMsg('stop_loss', 'Formatted: ' + formattedPrice, 'info');
        });
    }
}

/**
 * Calculate risk and provide recommendations when both prices are available
 */
function calculateRiskAndRecommendations(buyingPrice, stopLoss, tradeUtils) {
    // Calculate risk percentage
    tradeUtils.addParam('sysparm_name', 'calculateRisk');
    tradeUtils.addParam('sysparm_buying_price', buyingPrice);
    tradeUtils.addParam('sysparm_stop_loss', stopLoss);
    tradeUtils.getXMLAnswer(function(response) {
        var riskResult = JSON.parse(response);

        if (riskResult.success) {
            // Show risk information
            var riskMessage = 'Risk: $' + riskResult.riskAmount + ' (' + riskResult.riskPercentage + '%)';
            g_form.addInfoMessage('💡 ' + riskMessage);

            // Get trading recommendations
            var recommendationUtils = new GlideAjax('TradeBookUtils');
            recommendationUtils.addParam('sysparm_name', 'getTradeRecommendations');
            recommendationUtils.addParam('sysparm_buying_price', buyingPrice);
            recommendationUtils.addParam('sysparm_stop_loss', stopLoss);
            recommendationUtils.getXMLAnswer(function(recResponse) {
                var recResult = JSON.parse(recResponse);

                if (recResult.success && recResult.recommendations) {
                    // Display recommendations
                    recResult.recommendations.forEach(function(rec) {
                        var icon = rec.type === 'warning' ? '⚠️' : 
                                  rec.type === 'success' ? '✅' : 'ℹ️';
                        g_form.addInfoMessage(icon + ' ' + rec.message);
                    });

                    // Show suggested target price
                    if (recResult.suggestedTarget) {
                        g_form.addInfoMessage('🎯 Suggested target price (2:1 ratio): $' + recResult.suggestedTarget);
                    }
                }
            });
        } else {
            g_form.addErrorMessage('Error calculating risk: ' + riskResult.message);
        }
    });
}
